"""Summarize log lines by level (see SPEC_FEATURE.md)."""

from collections import Counter


def summarize(lines):
    by_level = Counter()
    errors = Counter()
    total = 0
    for line in lines:
        if not line.strip():
            continue
        total += 1
        parts = line.split(" ", 1)
        level = parts[0]
        by_level[level] += 1
        if level == "ERROR" and len(parts) > 1:
            errors[parts[1]] += 1
    return {
        "total": total,
        "by_level": dict(by_level),
        "top_errors": errors.most_common(3),
    }
